<?php get_header(); ?>
<main id="contenido"><?php while(have_posts()):the_post();$term=mee_article_term();$demo=get_post_meta(get_the_ID(),'_mee_demo',true);$area=get_post_meta(get_the_ID(),'_mee_area',true);$topic=get_post_meta(get_the_ID(),'_mee_topic',true); ?>
<nav class="breadcrumbs" aria-label="Ruta de navegación"><ol><?php $breadcrumbs=mee_breadcrumb_items();array_pop($breadcrumbs);foreach($breadcrumbs as$breadcrumb): ?><li><a href="<?php echo esc_url($breadcrumb['url']); ?>"><?php echo esc_html($breadcrumb['name']); ?></a></li><?php endforeach; ?></ol></nav>
<article <?php post_class('mee-article'); ?>><header class="mee-article-heading"><p class="eyebrow"><?php $reading=mee_reading_details(get_the_ID());echo esc_html($reading['level']).' · Unos '.esc_html($reading['minutes']).' min de lectura'; ?></p><h1><?php the_title(); ?><span class="title-dot">.</span></h1><p class="mee-byline">Anacleto · firma editorial de MEE</p><?php if(has_excerpt()): ?><p class="mee-standfirst"><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?><?php if($demo): ?><p class="mee-demo-banner">Entrada de prueba para explorar este tema. Ejemplos hipotéticos y contenido pendiente de revisión editorial.</p><?php endif; ?></header>
<?php if(has_post_thumbnail())the_post_thumbnail('full',['class'=>'mee-feature','fetchpriority'=>'high','sizes'=>'(max-width:1200px) 100vw, 1200px']); ?>
<div class="mee-reading-layout"><?php preg_match_all('/<h2\s+id="([^"]+)"[^>]*>(.*?)<\/h2>/si',get_the_content(),$headings,PREG_SET_ORDER); if($headings): ?><nav class="mee-article-toc" aria-label="En esta entrada"><span>En esta entrada</span><?php foreach($headings as$heading): ?><a href="#<?php echo esc_attr($heading[1]); ?>"><?php echo esc_html(wp_strip_all_tags($heading[2])); ?></a><?php endforeach; ?></nav><?php endif; ?><div class="entry-content"><?php the_content(); ?></div></div>
<?php mee_reading_continuation(get_the_ID()); ?>
<?php if($area): ?><section class="mee-article-next"><p>Esta idea forma parte de un mapa más grande.</p><a href="https://moevec.org/areas/<?php echo esc_attr($area); ?>/#<?php echo esc_attr($topic); ?>">Volver a su área <span aria-hidden="true">↗</span></a></section><?php echo do_shortcode('[mee_conversacion area="'.esc_attr($area).'"]');endif; ?>
<?php $related_ids=mee_related_article_ids(get_the_ID(),$term);$related=new WP_Query(['post_type'=>'post','post__in'=>$related_ids?:[0],'orderby'=>'post__in','posts_per_page'=>3,'no_found_rows'=>true]);if($related->have_posts()): ?><section class="mee-related"><h2>Seguir conectando ideas.</h2><div><?php while($related->have_posts()):$related->the_post(); ?><a href="<?php the_permalink(); ?>"><?php the_post_thumbnail('mee-card',['loading'=>'lazy']); ?><h3><?php the_title(); ?></h3></a><?php endwhile;wp_reset_postdata(); ?></div></section><?php endif; ?>
</article><?php endwhile; ?></main><?php get_footer(); ?>
